const items = $input.all();
const results = [];

for (const item of items) {
  const body = item.json.text || item.json.html || '';

  // Extract name
  const nameMatch = body.match(/(?:name|full\s*name|customer)\s*[:\-]\s*(.+)/i);
  const name = nameMatch ? nameMatch[1].trim().split('\n')[0].trim() : (item.json.from?.text || 'Unknown');

  // Extract phone
  const phoneMatch = body.match(/(?:phone|tel|mobile|cell|number)\s*[:\-]\s*([\d\s\-().+]+)/i);
  let phone = phoneMatch ? phoneMatch[1].trim() : '';
  if (!phone) {
    const bodyPhone = body.match(/(\+?1?\s*[-.](\s*\(?\d{3}\)?\s*[-.]?\s*\d{3}\s*[-.]?\s*\d{4})/);
    phone = bodyPhone ? bodyPhone[1] : '';
  }
  phone = phone.replace(/[^\d+]/g, '');

  // Extract email
  const emailMatch = body.match(/(?:email|e-mail)\s*[:\-]\s*([\w.+-]+@[\w.-]+\.\w+)/i);
  const email = emailMatch ? emailMatch[1].trim() : (item.json.from?.address || '');

  // Extract message
  const msgMatch = body.match(/(?:message|comments?|details?)\s*[:\-]\s*([\s\S]+?)(?:\n\s*\n|$)/i);
  const message = msgMatch ? msgMatch[1].trim().substring(0, 500) : body.substring(0, 500).trim();

  if (phone) {
    results.push({ json: { name, phone, email, message, timestamp: new Date().toISOString() } });
  }
}

return results;
